// Tabiato sends { task, system, user }. Pick the model per task here —
// change models in n8n without redeploying the app. Check console.groq.com/docs/models.
const body = $input.first().json.body ?? {};
const task = String(body.task ?? '');
const models = {
  memory_book:   { model: 'llama-3.3-70b-versatile', temperature: 0.7 },
  insight:       { model: 'llama-3.3-70b-versatile', temperature: 0.5 },
  intel_notes:   { model: 'llama-3.3-70b-versatile', temperature: 0.3 },
  hazard_advice: { model: 'llama-3.3-70b-versatile', temperature: 0.3 },
  rain_replan:   { model: 'llama-3.1-8b-instant',    temperature: 0.4 },
  plan_titles:   { model: 'llama-3.1-8b-instant',    temperature: 0.6 },
  note_draft:    { model: 'llama-3.1-8b-instant',    temperature: 0.7 },
  search_summary:{ model: 'llama-3.1-8b-instant',    temperature: 0.3 },
};
if (!models[task] || typeof body.system !== 'string' || typeof body.user !== 'string') {
  throw new Error(`Unknown task "${task}" or missing prompt`);
}
return [{ json: { task, system: body.system, user: body.user, ...models[task] } }];

// The app validates the result again with zod — this just guarantees JSON back.
const content = $input.first().json.choices?.[0]?.message?.content ?? '{}';
let data;
try { data = JSON.parse(content); } catch (e) { throw new Error('Model did not return JSON'); }
return [{ json: { ok: true, task: $('Pick model for task').first().json.task, data } }];
